result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/jpath.py", "content": """"A small JSONPath subset.

Supported syntax:
    $                root of the document
    .name            child access by name
    ['name']         child access via bracketed single-quoted string
    [0], [-1]        array index (negative counts from the end)
    [*]              wildcard over arrays (elements) and objects (values)
    [start:end]      array slice (Python semantics, negatives allowed)
    ..name           recursive descent: every `name` member at any depth

Results are returned in document order.  Malformed paths raise
JsonPathError carrying the offending position in the path string.
"""

from __future__ import annotations

import re
from dataclasses import dataclass


class JsonPathError(ValueError):
    """Raised when a JSONPath expression cannot be parsed."""

    def __init__(self, message: str, position: int):
        super().__init__(f"{message} at position {position}")
        self.position = position
        self.message = message


# --------------------------------------------------------------------------
# Selectors
# --------------------------------------------------------------------------

@dataclass(frozen=True)
class ChildSelector:
    name: str

    def apply(self, nodes):
        for node in nodes:
            if isinstance(node, dict) and self.name in node:
                yield node[self.name]


@dataclass(frozen=True)
class IndexSelector:
    index: int

    def apply(self, nodes):
        for node in nodes:
            if isinstance(node, list):
                try:
                    yield node[self.index]
                except IndexError:
                    pass


@dataclass(frozen=True)
class WildcardSelector:

    def apply(self, nodes):
        for node in nodes:
            if isinstance(node, list):
                yield from node
            elif isinstance(node, dict):
                yield from node.values()


@dataclass(frozen=True)
class SliceSelector:
    start: int | None
    end: int | None

    def apply(self, nodes):
        for node in nodes:
            if isinstance(node, list):
                yield from node[self.start:self.end]


@dataclass(frozen=True)
class RecursiveSelector:
    """`..name`: yields node[name] for this node and every descendant."""

    name: str

    def _walk(self, node):
        # Pre-order traversal == document order.
        yield node
        if isinstance(node, list):
            for item in node:
                yield from self._walk(item)
        elif isinstance(node, dict):
            for value in node.values():
                yield from self._walk(value)

    def apply(self, nodes):
        for node in nodes:
            for candidate in self._walk(node):
                if isinstance(candidate, dict) and self.name in candidate:
                    yield candidate[self.name]


# --------------------------------------------------------------------------
# Parser
# --------------------------------------------------------------------------

_NAME_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_\-]*")
_INT_RE = re.compile(r"-?\d+")


def _parse_string_literal(path: str, i: int) -> tuple[str, int]:
    """Parse a single-quoted string starting at ``i`` (which points at ')."""
    quote = path[i]
    i += 1
    chars = []
    while i < len(path):
        ch = path[i]
        if ch == "\\" and i + 1 < len(path):
            nxt = path[i + 1]
            if nxt == "'" or nxt == "\\":
                chars.append(nxt)
                i += 2
                continue
            raise JsonPathError(f"invalid escape '\\{nxt}' in string literal", i)
        if ch == quote:
            return "".join(chars), i + 1
        chars.append(ch)
        i += 1
    raise JsonPathError("unterminated string literal", i)


def _parse_bracket(path: str, i: int):
    """Parse a bracketed selector; ``i`` points at '['."""
    assert path[i] == "["
    i += 1
    _skip_ws = lambda j: j  # no whitespace allowed inside brackets (kept strict)

    if i >= len(path):
        raise JsonPathError("unterminated '['", i)

    # Wildcard
    if path[i] == "*":
        if i + 1 >= len(path) or path[i + 1] != "]":
            raise JsonPathError("expected ']' after '*'", i + 1)
        return WildcardSelector(), i + 2

    # Bracketed string child access: ['name']
    if path[i] == "'":
        name, i = _parse_string_literal(path, i)
        if i >= len(path) or path[i] != "]":
            raise JsonPathError("expected ']' after string literal", i)
        return ChildSelector(name), i + 1

    # Index or slice: [0], [-1], [start:end], [:end], [start:], [:]
    m = _INT_RE.match(path, i)
    if m or path[i] == ":":
        start = int(m.group()) if m else None
        i = m.end() if m else i
        if i < len(path) and path[i] == ":":
            i += 1
            m2 = _INT_RE.match(path, i)
            end = int(m2.group()) if m2 else None
            i = m2.end() if m2 else i
            if i >= len(path) or path[i] != "]":
                raise JsonPathError("expected ']' after slice", i)
            return SliceSelector(start, end), i + 1
        if start is None:
            raise JsonPathError("expected index, slice or '*'", i)
        if i >= len(path) or path[i] != "]":
            raise JsonPathError("expected ']' after index", i)
        return IndexSelector(start), i + 1

    raise JsonPathError(
        "expected string literal, index, slice or '*' after '['", i
    )


def parse(path: str) -> list:
    """Parse a JSONPath expression into an ordered list of selectors."""
    if not isinstance(path, str):
        raise JsonPathError("path must be a string", 0)
    if len(path) == 0 or path[0] != "$":
        raise JsonPathError("path must start with '$'", 0)
    i = 1
    selectors: list = []
    while i < len(path):
        ch = path[i]
        if ch == ".":
            if i + 1 < len(path) and path[i + 1] == ".":
                # Recursive descent: '..name'
                i += 2
                m = _NAME_RE.match(path, i)
                if not m:
                    raise JsonPathError("expected a name after '..'", i)
                selectors.append(RecursiveSelector(m.group()))
                i = m.end()
            else:
                # Child access: '.name'
                i += 1
                m = _NAME_RE.match(path, i)
                if not m:
                    raise JsonPathError("expected a name after '.'", i)
                selectors.append(ChildSelector(m.group()))
                i = m.end()
        elif ch == "[":
            sel, i = _parse_bracket(path, i)
            selectors.append(sel)
        else:
            raise JsonPathError(f"unexpected character {ch!r}", i)
    return selectors


# --------------------------------------------------------------------------
# Public API
# --------------------------------------------------------------------------

def find(path: str, doc) -> list:
    """Evaluate ``path`` against ``doc``; return matches in document order."""
    selectors = parse(path)
    nodes = [doc]
    for sel in selectors:
        nodes = list(sel.apply(nodes))
    return nodes
