from jpath import JsonPathError, find


BOOKSTORE = {
    "store": {
        "book": [
            {
                "category": "reference",
                "author": "Nigel Rees",
                "title": "Sayings of the Century",
                "price": 8.95,
            },
            {
                "category": "fiction",
                "author": "Evelyn Waugh",
                "title": "Sword of Honour",
                "price": 12.99,
            },
            {
                "category": "fiction",
                "author": "Herman Melville",
                "title": "Moby Dick",
                "isbn": "0-553-21311-3",
                "price": 8.99,
            },
            {
                "category": "fiction",
                "author": "J. R. R. Tolkien",
                "title": "The Lord of the Rings",
                "isbn": "0-395-19395-8",
                "price": 22.99,
            },
        ],
        "bicycle": {"color": "red", "price": 19.95},
    }
}


def test_root():
    assert find("$", BOOKSTORE) == [BOOKSTORE]


def test_child_access():
    assert find("$.store.bicycle.color", BOOKSTORE) == ["red"]


def test_bracket_child_access():
    assert find("$['store']['bicycle'].color", BOOKSTORE) == ["red"]


def test_wildcard_over_books_authors():
    assert find("$.store.book[*].author", BOOKSTORE) == [
        "Nigel Rees",
        "Evelyn Waugh",
        "Herman Melville",
        "J. R. R. Tolkien",
    ]


def test_recursive_author():
    assert find("$..author", BOOKSTORE) == [
        "Nigel Rees",
        "Evelyn Waugh",
        "Herman Melville",
        "J. R. R. Tolkien",
    ]


def test_all_prices_recursive():
    # Bicycle's price comes last: it appears after the books in document order.
    assert find("$..price", BOOKSTORE) == [8.95, 12.99, 8.99, 22.99, 19.95]


def test_store_descendant_prices():
    assert find("$.store..price", BOOKSTORE) == [8.95, 12.99, 8.99, 22.99, 19.95]


def test_slice_middle():
    assert find("$.store.book[1:3].title", BOOKSTORE) == [
        "Sword of Honour",
        "Moby Dick",
    ]


def test_slice_prefix():
    assert find("$.store.book[:2].title", BOOKSTORE) == [
        "Sayings of the Century",
        "Sword of Honour",
    ]


def test_slice_open_end():
    assert find("$.store.book[2:].title", BOOKSTORE) == [
        "Moby Dick",
        "The Lord of the Rings",
    ]


def test_slice_negative():
    assert find("$.store.book[-2:].title", BOOKSTORE) == [
        "Moby Dick",
        "The Lord of the Rings",
    ]


def test_negative_index_last_book():
    assert find("$.store.book[-1].title", BOOKSTORE) == ["The Lord of the Rings"]
    assert find("$..book[-1].title", BOOKSTORE) == ["The Lord of the Rings"]


def test_index_select():
    assert find("$..book[2]", BOOKSTORE) == [
        {
            "category": "fiction",
            "author": "Herman Melville",
            "title": "Moby Dick",
            "isbn": "0-553-21311-3",
            "price": 8.99,
        }
    ]
    assert find("$.store.book[0].title", BOOKSTORE) == ["Sayings of the Century"]


def test_wildcard_over_object():
    assert find("$.store.bicycle[*]", BOOKSTORE) == ["red", 19.95]


def test_wildcard_no_match_on_scalar():
    assert find("$.store.bicycle.color[*]", BOOKSTORE) == []


def test_missing_key_yields_empty():
    assert find("$.store.missing", BOOKSTORE) == []
    assert find("$.store.book[10]", BOOKSTORE) == []
    assert find("$.store.book[-10]", BOOKSTORE) == []


def test_recursive_into_nested_lists():
    doc = {"a": [{"b": 1}, {"c": {"b": 2}}]}
    assert find("$..b", doc) == [1, 2]


@pytest.mark.parametrize(
    "bad_path,pos",
    [
        ("store.book", 0),          # missing leading $
        ("", 0),
        ("$.store.", 8),            # dangling dot without a name
        ("$..", 2),                 # recursive descent without a name
        ("$.store[", 8),            # unterminated bracket
        ("$['store\"", 2),          # unterminated string literal
        ("$.store[1", 9),           # missing closing bracket on index
        ("$.store[1:", 9),          # unterminated slice
        ("$.store[x]", 8),          # junk inside brackets
        ("$.store[1:2:3]", 11),     # step is not supported
        ("$.store book", 8),        # stray character between segments
    ],
)
def test_errors(bad_path, pos):
    with pytest.raises(JsonPathError) as excinfo:
        find(bad_path, BOOKSTORE)
    assert excinfo.value.position == pos
    assert str(pos) in str(excinfo.value)


def test_error_is_valueerror():
    assert issubclass(JsonPathError, ValueError)
